"""Contact sheet for substitute teachers."""

import typing

from rosterkit import models


def contact_rows(students: typing.Iterable[models.Student]) -> typing.List[str]:
    """Text rows of name, section and email, sorted by display name.

    Raises ValueError for an empty list or for a student with no email.
    """
    members = sorted(students, key=lambda student: student.display_name)
    if not members:
        raise ValueError("no students to list")
    for student in members:
        if not student.email:
            raise ValueError(
                "student has no email: {}".format(student.display_name)
            )
    name_width = 0
    section_width = 0
    for student in members:
        name_width = max(name_width, len(student.display_name))
        section_width = max(section_width, len(student.section))
    rows = []
    for student in members:
        rows.append(
            "{}  {}  {}".format(
                student.display_name.ljust(name_width),
                student.section.ljust(section_width),
                student.email,
            )
        )
    return rows
