cat > tests/test_contacts.py <<'EOF'
import unittest

from rosterkit import contacts
from rosterkit import models


def make_student(last, first, section, email):
    return models.Student("1", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name_and_aligned(self):
        students = [
            make_student("Zed", "Amy", "B", "amy@example.invalid"),
            make_student("Abbott", "Bo", "A", "bo@example.invalid"),
        ]
        self.assertEqual(
            contacts.contact_rows(students),
            [
                "Abbott, Bo  A  bo@example.invalid",
                "Zed, Amy    B  amy@example.invalid",
            ],
        )

    def test_section_column_pads_to_longest(self):
        students = [
            make_student("Lee", "Al", "10", "al@example.invalid"),
            make_student("Moe", "Bo", "9", "bo@example.invalid"),
        ]
        rows = contacts.contact_rows(students)
        self.assertEqual(rows[0].index("al@"), rows[1].index("bo@"))

    def test_missing_email_names_the_student(self):
        students = [
            make_student("Lee", "Al", "A", "al@example.invalid"),
            make_student("Moe", "Bo", "A", None),
        ]
        with self.assertRaises(ValueError) as caught:
            contacts.contact_rows(students)
        self.assertIn("Moe, Bo", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        with self.assertRaises(ValueError):
            contacts.contact_rows([make_student("Moe", "Bo", "A", "")])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contacts.contact_rows([])


if __name__ == "__main__":
    unittest.main()
